import { Mesub } from '@mesub/node';

const mesub = new Mesub(); // reads MESUB_API_KEY

// true or false, cached, safe during an outage
if (await mesub.hasAccess({ external_id: 'user_42' }, 'pro')) {
    // serve what is paid
}

// the whole answer
const answer = await mesub.access({ external_id: 'user_42' }, 'pro');

// every plan they have anything on
const { plans } = await mesub.accessList({ external_id: 'user_42' });

import { Mesub } from '@mesub/node';

const mesub = new Mesub(); // reads MESUB_API_KEY

const plans = await mesub.plans.list();

import { Mesub } from '@mesub/node';

const mesub = new Mesub(); // reads MESUB_API_KEY

const plan = await mesub.plans.retrieve('pro');

import { Mesub } from '@mesub/node';

const mesub = new Mesub(); // reads MESUB_API_KEY

const { subscription, transaction, terms, costs } =
    await mesub.subscriptions.create({
        plan: 'pro',
        wallet, // the wallet that signs and pays
        external_id: 'user_42', // optional: your own id for this customer
        email: 'ada@example.com', // optional: where their notices go
    });

import { Mesub } from '@mesub/node';

const mesub = new Mesub(); // reads MESUB_API_KEY

const { data, has_more } = await mesub.subscriptions.list({
    external_id: 'user_42',
});

// every page
for await (const sub of mesub.subscriptions.listAll({ external_id: 'user_42' })) {
    // ...
}

